// vehicle_documents_search.js — generated by Generate Module

$(document).ready(function () {

  const statusBadge = function (data) {
    const c = { active: 'success', inactive: 'danger' };
    return '<span class="badge text-bg-' + (c[data] || 'secondary') + '">' + data + '</span>';
  };

  // ── Vehicle picker ───────────────────────────────────────────────────────
  const vehiclePicker = $('#vdcVehiclePickerTable').DataTable({
    ajax: { url: '/modules/master_files/staff_fleet/vehicle_master_file/vehicle_master_file_data.php?action=list', dataSrc: '' },
    columns: [
      { data: 'ref' },
      { data: 'plate_number' },
      { data: 'make' },
      { data: 'model' },
      { data: 'type' },
      { data: 'status', render: statusBadge },
    ],
    pageLength: 10,
    searching: true,
    dom: '<"d-flex justify-content-between align-items-center mb-2"f>rtip',
    language: { search: 'Filter:', info: 'Showing _START_ to _END_ of _TOTAL_' },
  });

  $('#vdcVehiclePickerTable tbody').on('click', 'tr', function () {
    const data = vehiclePicker.row(this).data();
    if (!data) return;
    bootstrap.Modal.getInstance(document.getElementById('vdcVehiclePickerModal')).hide();
    document.dispatchEvent(new CustomEvent('vdc-vehicle-selected', { detail: data }));
  });

  $('#vdcVehiclePickerModal').on('shown.bs.modal', function () {
    vehiclePicker.ajax.reload(null, false);
    vehiclePicker.columns.adjust();
  });

  // ── Document Type picker ─────────────────────────────────────────────────
  const documentTypePicker = $('#vdcDocumentTypePickerTable').DataTable({
    ajax: { url: '/modules/master_files/vehicle/vehicle_document_types/vehicle_document_types_data.php?action=list', dataSrc: '' },
    columns: [
      { data: 'ref' },
      { data: 'code' },
      { data: 'name' },
      { data: 'status', render: statusBadge },
    ],
    pageLength: 10,
    searching: true,
    dom: '<"d-flex justify-content-between align-items-center mb-2"f>rtip',
    language: { search: 'Filter:', info: 'Showing _START_ to _END_ of _TOTAL_' },
  });

  $('#vdcDocumentTypePickerTable tbody').on('click', 'tr', function () {
    const data = documentTypePicker.row(this).data();
    if (!data) return;
    bootstrap.Modal.getInstance(document.getElementById('vdcDocumentTypePickerModal')).hide();
    document.dispatchEvent(new CustomEvent('vdc-document-type-selected', { detail: data }));
  });

  $('#vdcDocumentTypePickerModal').on('shown.bs.modal', function () {
    documentTypePicker.ajax.reload(null, false);
    documentTypePicker.columns.adjust();
  });

  const table = $('#vehicleDocumentsSearchTable').DataTable({
    ajax: { url: '/modules/operations/fleet_maintenance/vehicle_documents/vehicle_documents_data.php?action=list', dataSrc: '' },
    columns: [
      { data: 'ref' },
      { data: 'm_vehicles.plate_number', defaultContent: '' },
      { data: 'm_vehicle_document_types.name', defaultContent: '' },
      { data: 'document_number' },
      { data: 'issue_date' },
      { data: 'expiry_date' },
      { data: 'issued_by' },
      { data: 'attachment' },
      { data: 'remarks' },
    ],
    pageLength: 10,
    lengthMenu: [5, 10, 25, 50],
    dom: '<"d-flex justify-content-between align-items-center mb-2"Bf>rtip',
    buttons: [
      { extend: 'copy',  className: 'btn btn-sm btn-secondary' },
      { extend: 'excel', className: 'btn btn-sm btn-success',  text: '<i class="bi bi-file-earmark-excel me-1"></i>Excel' },
      { extend: 'csv',   className: 'btn btn-sm btn-info',     text: '<i class="bi bi-filetype-csv me-1"></i>CSV' },
      { extend: 'pdf',   className: 'btn btn-sm btn-danger',   text: '<i class="bi bi-file-earmark-pdf me-1"></i>PDF' },
      { extend: 'print', className: 'btn btn-sm btn-secondary' },
    ],
    language: {
      search: 'Global search:',
      lengthMenu: 'Show _MENU_ entries',
      info: 'Showing _START_ to _END_ of _TOTAL_ Vehicle Documents records',
    },
  });

  $('#vehicleDocumentsSearchTable tbody').on('click', 'tr', function () {
    const data = table.row(this).data();
    if (!data) return;
    bootstrap.Modal.getInstance(document.getElementById('vehicleDocumentsSearchModal')).hide();
    document.dispatchEvent(new CustomEvent('vehicle_documents-selected', { detail: data }));
  });

  $('#vehicleDocumentsSearchModal').on('shown.bs.modal', function () {
    table.ajax.reload(null, false);
    table.columns.adjust();
  });

});
